// Exnoria - sup.ticket.escalate
// Build escalation task and tag contact

const webhook = $("Webhook").first().json.body;
const contact = $input.first().json;

const { contact_id, ticket_id, signal_id, signal_severity, open_days, reason } = webhook;

const firstname = contact.properties?.firstname?.value ?? 'Contact';
const lastname  = contact.properties?.lastname?.value  ?? '';
const email     = contact.properties?.email?.value     ?? '';
const company   = contact.properties?.company?.value   ?? '';

// Determine urgency tier based on severity and open days
let urgency = 'normal';
if (signal_severity > 0.8 || open_days > 7) urgency = 'critical';
else if (signal_severity > 0.6 || open_days > 3) urgency = 'high';

const escalatedAt = new Date(new Date().setUTCHours(0,0,0,0)).getTime();

const taskBody = [
  '[ESCALATION] ' + firstname + ' ' + lastname + ' - ' + company,
  'Ticket: ' + (ticket_id || 'N/A'),
  'Signal: ' + signal_id + ' (severity: ' + signal_severity + ')',
  'Open days: ' + open_days,
  'Urgency: ' + urgency,
  'Reason: ' + (reason || 'Auto-escalated by Exnoria'),
  'Email: ' + email,
  'Contact ID: ' + contact_id
].join('\n');

return [{
  json: {
    contact_id,
    ticket_id: ticket_id || 'N/A',
    signal_id,
    email,
    firstname,
    lastname,
    company,
    urgency,
    escalated_at: escalatedAt,
    task_subject: '[Exnoria Escalation] ' + firstname + ' ' + lastname + ' - ' + urgency.toUpperCase(),
    task_body: taskBody,
    reason: reason || 'Auto-escalated by Exnoria'
  }
}];

// Simulate -- HubSpot task creation
// Replace with real HubSpot task API when ready

const data = $input.first().json;

return [{
  json: {
    ...data,
    task_created: true,
    task_id: 'task_sim_' + Date.now(),
    simulated: true
  }
}];
